using System;using System.IO;using System.Text;using System.Collections;using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckTerrierRacing {
public sealed class TerrierDessertProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsTerrierDessert")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.TerrierDessertProbe",false);UnityEditor.SessionState.SetBool("LWS.TerrierDessertProbe",false);
#endif
 if(run){var g=new GameObject("Actual falling trucks and dessert validation");DontDestroyOnLoad(g);g.AddComponent<TerrierDessertProbe>();}}
 TerrierMatch m;string folder,saved;bool had,restored;int errors;readonly StringBuilder log=new StringBuilder();void Check(bool ok,string label){if(!ok)errors++;log.AppendLine((ok?"PASS ":"FAIL ")+label);File.WriteAllText(folder+"/progress.txt",log.ToString());}void Error(string s,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){errors++;log.AppendLine("ERROR "+s);}}
 IEnumerator Fresh(){m.SetupScreen();m.AllBots();Check(m.StartMatch(),"AI setup starts");while(m.Phase==TerrierPhase.Countdown)yield return null;m.crowd.Stop();m.course.weather.Configure(1,1,0);for(int i=1;i<12;i++)m.racers[i].Wreck();}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("TerrierDessertEvidence");m=FindAnyObjectByType<TerrierMatch>();if(m==null){SportsNavigation.LoadSport(SportsNavigation.Terrier);yield return null;m=FindAnyObjectByType<TerrierMatch>();}yield return null;had=LWS.TruckSports.SportsPrefs.HasKey(m.PreferenceKey);saved=LWS.TruckSports.SportsPrefs.GetString(m.PreferenceKey);Application.logMessageReceived+=Error;
 yield return Fresh();var r=m.racers[0];var p=m.course.World(new Vector3(m.course.HalfWidth(75)+8,3,75));r.truck.body.position=p;r.truck.body.rotation=m.course.DrivingRotation;r.truck.body.linearVelocity=m.course.geometry.right*7+Vector3.down;float end=Time.realtimeSinceStartup+8;while(!r.Creamed&&r.Alive&&Time.realtimeSinceStartup<end)yield return null;Check(r.OffCourse&&r.Creamed&&m.dessert.Squishes==1,"actual off-course gravity fall enters cream once");Check(!r.Finished&&m.HeatWinner<0&&r.truck.visuals.gameObject.activeSelf&&!r.truck.body.isKinematic,"cream failure retains visible physical truck and awards no finish");Capture("cream-landing.png",m.dessert.basin.position+Vector3.up*4,new Vector3(65,65,-100));yield return new WaitForSeconds(.5f);Check(m.dessert.Squishes==1,"sustained cream contact cannot repeat squish");Check(r.truck.body.position.y>m.dessert.basin.position.y-5,"real cream collision supports truck instead of falling through basin");
 yield return Fresh();for(int i=1;i<12;i++){m.racers[i].Prepare(m.course.StartPosition(i,1));m.racers[i].Release();}for(int i=0;i<12;i++)m.QueueWreck(i,Time.fixedTime,"ALL_TWELVE_PHYSICAL_DEBRIS_FIXTURE");yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();Check(m.wrecks.Emissions==12&&m.wrecks.ActiveCount==144,"all twelve trucks emit twelve actual physical pieces each");int moving=0;foreach(var piece in m.wrecks.pieces)if(piece.body.gameObject.activeSelf&&!piece.body.isKinematic&&piece.body.linearVelocity.sqrMagnitude>1)moving++;Check(moving>=120,"wreck fragments have real bounded Rigidbody motion");yield return new WaitForSeconds(.4f);Capture("actual-truck-pieces.png",m.course.World(new Vector3(0,1,2)),m.course.Heading*new Vector3(15,13,-22));end=Time.realtimeSinceStartup+6;while(m.Phase==TerrierPhase.Race&&Time.realtimeSinceStartup<end)yield return null;Check(m.Phase==TerrierPhase.Replay&&m.replay.Playing,"all-wreck heat reaches recorded replay after aftermath");m.replay.Seek(.5f);int ghosts=0;foreach(var piece in m.wrecks.pieces)if(piece.ghost.gameObject.activeSelf)ghosts++;Check(ghosts>=120,"actual debris poses replay as nonphysical visible meshes");
 log.AppendLine("ERRORS="+errors+". Controlled initial poses, real gravity/contact and Rigidbody simulation; no hardware/human playtest.");File.WriteAllText(folder+"/result.txt",log.ToString());Debug.Log("TERRIER_DESSERT_PROBE_COMPLETE "+log);Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);}
 void Capture(string name,Vector3 target,Vector3 offset){var c=m.broadcast.view;var oldP=c.transform.position;var oldQ=c.transform.rotation;var oldTarget=c.targetTexture;var oldRect=c.rect;var oldActive=RenderTexture.active;var rt=RenderTexture.GetTemporary(1280,720,24);c.targetTexture=rt;c.rect=new Rect(0,0,1,1);c.transform.SetPositionAndRotation(target+offset,Quaternion.LookRotation(-offset));c.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name,tex.EncodeToPNG());Destroy(tex);c.targetTexture=oldTarget;c.rect=oldRect;c.transform.SetPositionAndRotation(oldP,oldQ);RenderTexture.active=oldActive;RenderTexture.ReleaseTemporary(rt);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){m.SetupScreen();if(had)LWS.TruckSports.SportsPrefs.SetString(m.PreferenceKey,saved);else LWS.TruckSports.SportsPrefs.DeleteKey(m.PreferenceKey);LWS.TruckSports.SportsPrefs.Save();}Time.timeScale=1;}void OnDestroy(){Restore();}
#endif
}
